package com.bank.poison.dlt;

import com.bank.poison.model.TransferRecord;
import java.util.*;

// Simulates transfers.DLT carrying the record plus error metadata for replay.
public class DeadLetterTopic {
    public static class DeadLetter {
        final TransferRecord record;
        final String originalTopic;
        final String errorMessage;
        final int attempts;
        DeadLetter(TransferRecord r, String topic, String err, int attempts) {
            this.record = r; this.originalTopic = topic;
            this.errorMessage = err; this.attempts = attempts;
        }
        @Override public String toString() {
            return "DLT{" + record + ", from=" + originalTopic
                 + ", attempts=" + attempts + ", error='" + errorMessage + "'}";
        }
    }

    private final List<DeadLetter> letters = new ArrayList<>();

    public void publish(TransferRecord r, String topic, String err, int attempts) {
        letters.add(new DeadLetter(r, topic, err, attempts));
    }

    public List<DeadLetter> getLetters() { return letters; }
}
