package com.bank.poison.consumer;

import com.bank.poison.dlt.DeadLetterTopic;
import com.bank.poison.exception.ValidationException;
import com.bank.poison.model.TransferRecord;
import java.math.BigDecimal;
import java.util.logging.*;

public class SettlementConsumer {
    private static final Logger log = Logger.getLogger(SettlementConsumer.class.getName());
    private static final int MAX_ATTEMPTS = 3;

    private final DeadLetterTopic dlt;
    private long committedOffset = -1;
    private int settledCount = 0;

    public SettlementConsumer(DeadLetterTopic dlt) { this.dlt = dlt; }

    // Process one record with bounded retry, then route poison to the DLT.
    public void onRecord(TransferRecord r) {
        int attempts = 0;
        while (true) {
            attempts++;
            try {
                settle(r);
                committedOffset = r.getOffset(); // commit AFTER success
                settledCount++;
                log.info(() -> "Settled " + r + ", committed offset=" + committedOffset);
                return;
            } catch (ValidationException ve) {
                // Non-retryable: straight to DLT, do not waste retries.
                log.severe("Non-retryable failure for " + r + ": " + ve.getMessage());
                dlt.publish(r, "transfers", ve.getMessage(), attempts);
                committedOffset = r.getOffset(); // advance PAST the poison pill
                log.warning("Routed to transfers.DLT, committed offset=" + committedOffset);
                return;
            } catch (RuntimeException transient_) {
                if (attempts >= MAX_ATTEMPTS) {
                    log.severe("Retries exhausted for " + r + ": " + transient_.getMessage());
                    dlt.publish(r, "transfers", transient_.getMessage(), attempts);
                    committedOffset = r.getOffset();
                    log.warning("Routed to transfers.DLT after " + attempts + " attempts.");
                    return;
                }
                log.warning("Transient failure (attempt " + attempts + "), retrying: "
                    + transient_.getMessage());
            }
        }
    }

    private void settle(TransferRecord r) {
        if (r.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new ValidationException("amount must be positive, got " + r.getAmount());
        }
        // real logic would debit/credit accounts here
    }

    public long getCommittedOffset() { return committedOffset; }
    public int getSettledCount() { return settledCount; }
}
