package com.bank.poison;

import com.bank.poison.consumer.SettlementConsumer;
import com.bank.poison.dlt.DeadLetterTopic;
import com.bank.poison.model.TransferRecord;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class PoisonDemo {
    private static final Logger log = Logger.getLogger(PoisonDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DeadLetterTopic dlt = new DeadLetterTopic();
        SettlementConsumer consumer = new SettlementConsumer(dlt);

        List<TransferRecord> partition = List.of(
            new TransferRecord(10, "SAV2001", "CUR3001", new BigDecimal("50000")),
            new TransferRecord(11, "SAV2001", "CUR3001", new BigDecimal("-99")), // poison
            new TransferRecord(12, "CUR3001", "SAV2001", new BigDecimal("20000")));

        for (TransferRecord r : partition) consumer.onRecord(r);

        log.info("Settled OK = " + consumer.getSettledCount()
            + ", final committed offset = " + consumer.getCommittedOffset());
        log.info("Dead letters:");
        dlt.getLetters().forEach(dl -> log.info("  " + dl));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
